use crate::hold;
use std::cell::RefCell;
use std::fs;
use std::rc::Rc;

pub struct Plan {
    pub heat: bool,
    pub old: String,
    pub new: String,
    pub extra: String,
}

pub fn read_path(p: &str) -> Option<(hold::Sess, hold::Pool, Plan)> {
    let text = fs::read_to_string(p).ok()?;
    if text.trim().is_empty() { return None; }
    let mut n0 = None;
    let mut n1 = None;
    let mut cells: Option<Vec<String>> = None;
    let mut mode = None;
    let mut old = String::new();
    let mut new = String::new();
    let mut extra = String::new();
    for raw in text.lines() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') { continue; }
        let mut it = line.split_whitespace();
        match it.next()? {
            "tick" => { n0 = Some(it.next()?.parse().ok()?); if it.next().is_some() { return None; } }
            "mark" => { n1 = Some(it.next()?.parse().ok()?); if it.next().is_some() { return None; } }
            "bag" => {
                let v: Vec<String> = it.map(str::to_owned).collect();
                if v.is_empty() { return None; }
                cells = Some(v);
            }
            "mode" => {
                mode = match it.next()? { "heat" => Some(true), "peek" => Some(false), _ => return None };
                if it.next().is_some() { return None; }
            }
            "swap" => {
                old = it.next()?.to_owned(); new = it.next()?.to_owned();
                if it.next().is_some() { return None; }
            }
            "push" => {
                extra = it.next()?.to_owned();
                if it.next().is_some() { return None; }
            }
            _ => return None,
        }
    }
    let (n0, n1, cells, heat) = (n0?, n1?, cells?, mode?);
    if heat && (old.is_empty() || new.is_empty() || extra.is_empty()) { return None; }
    let ids: Vec<usize> = (0..cells.len()).collect();
    let sess = hold::Sess { n0, n1, ids: Rc::new(RefCell::new(ids)), flag: heat };
    Some((sess, hold::Pool { cells }, Plan { heat, old, new, extra }))
}

pub fn step(a: &mut hold::Sess, b: &mut hold::Pool, p: &Plan) {
    if p.heat {
        for cell in &mut b.cells {
            if *cell == p.old { *cell = p.new.clone(); }
        }
        b.cells.push(p.extra.clone());
        a.ids.borrow_mut().push(b.cells.len() - 1);
    }
    a.n0 = a.n0.saturating_add(1);
    a.n1 = a.n1.saturating_add(2);
}
