use std::collections::HashSet;
use std::fs;
use std::path::Path;

fn walk_cards(path: &Path, text: &mut String) -> std::io::Result<()> {
    for entry in fs::read_dir(path)? {
        let entry = entry?;
        let kind = entry.file_type()?;
        if kind.is_dir() { walk_cards(&entry.path(), text)?; }
        else if kind.is_file() {
            text.push_str(&fs::read_to_string(entry.path())?);
            text.push('\n');
        }
    }
    Ok(())
}

pub fn rib_d() -> i32 {
    let mut cards = String::new();
    if walk_cards(Path::new("/app/daycards"), &mut cards).is_err() { return 2; }
